code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            if (0 < r < h - 1 and 0 < c < w - 1
                and grid[r-1][c] == grid[r+1][c] == 3
                and grid[r][c-1] == grid[r][c+1] == 3):
                centers.append((r, c, grid[r][c]))
    owner = {}
    for r, c, color in centers:
        for pos in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            owner[pos] = (r, c)
    blank_centers = {(r, c) for r, c, color in centers if color == 0}

    def ray(r, c, color, dr, dc, vertical):
        i, j = r + dr, c + dc
        while 0 <= i < h and 0 <= j < w:
            if (i, j) in blank_centers:
                i += dr
                j += dc
                continue
            if original[i][j] == 3:
                if owner.get((i, j)) != (r, c):
                    break
            elif original[i][j] == 0:
                out[i][j] = color
            i += dr
            j += dc

    # Horizontal lines first; vertical lines win where colored lines cross.
    for r, c, color in centers:
        if color:
            ray(r, c, color, 0, -1, False)
            ray(r, c, color, 0, 1, False)
    for r, c, color in centers:
        if color:
            ray(r, c, color, -1, 0, True)
            ray(r, c, color, 1, 0, True)
    return out
'''
